openapi: 3.0.3
info:
  title: RedSalud Andina - API de Agenda y reservas
  version: 1.0.0
  description: Propuesta de diseño. El caso no define las rutas; los campos marcados "por definir" se completan con el equipo.
servers:
  - url: /api/v1
security:
  - bearerAuth: []
paths:
  /especialistas/{id}/cupos:
    get:
      summary: Lista los cupos libres de un especialista (RF-02)
      parameters:
        - { name: id, in: path, required: true, schema: { type: string } }
        - { name: desde, in: query, schema: { type: string, format: date } }
        - { name: hasta, in: query, schema: { type: string, format: date } }
      responses:
        '200': { description: Cupos libres en el rango (esquema Cupo por definir) }
        '403': { $ref: '#/components/responses/Prohibido' }
  /reservas:
    post:
      summary: Reserva un cupo para una interconsulta (RF-02)
      parameters:
        - $ref: '#/components/parameters/IdempotencyKey'
      requestBody:
        required: true
        content:
          application/json:
            schema: { $ref: '#/components/schemas/ReservaNueva' }
      responses:
        '201':
          description: Reserva confirmada; publica ReservaConfirmada
          content:
            application/json:
              schema: { $ref: '#/components/schemas/Reserva' }
        '409': { $ref: '#/components/responses/Conflicto' }
  /especialistas/{id}/agenda:
    put:
      summary: Publica o cambia la agenda del especialista (RF-02)
      parameters:
        - { name: id, in: path, required: true, schema: { type: string } }
        - $ref: '#/components/parameters/IdempotencyKey'
      responses:
        '200': { description: Agenda actualizada (esquema Agenda por definir) }
        '403': { $ref: '#/components/responses/Prohibido' }
components:
  securitySchemes:
    bearerAuth: { type: http, scheme: bearer, bearerFormat: JWT }
  parameters:
    IdempotencyKey:
      { name: Idempotency-Key, in: header, required: true, schema: { type: string, format: uuid } }
  responses:
    Prohibido:
      description: Sin permiso; Identidad publica AccesoDenegado hacia Auditoría
      content: { application/problem+json: { schema: { $ref: '#/components/schemas/Problema' } } }
    Conflicto:
      description: El cupo ya fue tomado o la clave de idempotencia llegó con otro cuerpo
      content: { application/problem+json: { schema: { $ref: '#/components/schemas/Problema' } } }
  schemas:
    Problema:
      type: object
      description: Problem Details (RFC 9457)
      properties:
        type: { type: string }
        title: { type: string }
        status: { type: integer }
        detail: { type: string }
    ReservaNueva:
      type: object
      required: [cupoId, interconsultaId, centroId]
      properties:
        cupoId: { type: string, format: uuid }
        interconsultaId: { type: string, format: uuid }
        centroId: { type: string }
    Reserva:
      type: object
      properties:
        id: { type: string, format: uuid }
        cupoId: { type: string, format: uuid }
        estado: { type: string, enum: [confirmada, pendiente_confirmacion, cancelada] }

openapi: 3.0.3
info:
  title: RedSalud Andina - API de Historial clínico
  version: 1.0.0
  description: Propuesta de diseño. El caso no define las rutas; los campos marcados "por definir" se completan con el equipo.
servers:
  - url: /api/v1
security:
  - bearerAuth: []
paths:
  /pacientes/{id}/historial:
    get:
      summary: Historial clínico en modo lectura (RF-06, RF-08)
      parameters:
        - { name: id, in: path, required: true, schema: { type: string } }
        - { name: motivo, in: query, required: true, schema: { type: string, minLength: 5 } }
      responses:
        '200':
          description: Historial con su fecha de actualización; publica HistorialConsultado
          content:
            application/json:
              schema: { $ref: '#/components/schemas/Historial' }
        '400': { description: Consulta sin motivo }
        '403': { $ref: '#/components/responses/Prohibido' }
components:
  securitySchemes:
    bearerAuth: { type: http, scheme: bearer, bearerFormat: JWT }
  parameters:
    IdempotencyKey:
      { name: Idempotency-Key, in: header, required: true, schema: { type: string, format: uuid } }
  responses:
    Prohibido:
      description: Sin permiso; Identidad publica AccesoDenegado hacia Auditoría
      content: { application/problem+json: { schema: { $ref: '#/components/schemas/Problema' } } }
  schemas:
    Problema:
      type: object
      description: Problem Details (RFC 9457)
      properties:
        type: { type: string }
        title: { type: string }
        status: { type: integer }
        detail: { type: string }
    Historial:
      type: object
      properties:
        pacienteId: { type: string }
        actualizadoEn: { type: string, format: date-time }
        antecedentes: { type: array, items: { type: string } }
        diagnosticos: { type: array, items: { type: string } }

openapi: 3.0.3
info:
  title: RedSalud Andina - API de Auditoría
  version: 1.0.0
  description: Propuesta de diseño. El caso no define las rutas; los campos marcados "por definir" se completan con el equipo.
servers:
  - url: /api/v1
security:
  - bearerAuth: []
paths:
  /auditoria/accesos:
    get:
      summary: Busca registros de acceso a datos clínicos (RF-08)
      parameters:
        - { name: usuario, in: query, schema: { type: string } }
        - { name: desde, in: query, schema: { type: string, format: date-time } }
        - { name: hasta, in: query, schema: { type: string, format: date-time } }
      responses:
        '200':
          description: Registros de acceso
          content:
            application/json:
              schema: { type: array, items: { $ref: '#/components/schemas/RegistroAcceso' } }
        '403': { $ref: '#/components/responses/Prohibido' }
components:
  securitySchemes:
    bearerAuth: { type: http, scheme: bearer, bearerFormat: JWT }
  parameters:
    IdempotencyKey:
      { name: Idempotency-Key, in: header, required: true, schema: { type: string, format: uuid } }
  responses:
    Prohibido:
      description: Sin permiso; Identidad publica AccesoDenegado hacia Auditoría
      content: { application/problem+json: { schema: { $ref: '#/components/schemas/Problema' } } }
  schemas:
    Problema:
      type: object
      description: Problem Details (RFC 9457)
      properties:
        type: { type: string }
        title: { type: string }
        status: { type: integer }
        detail: { type: string }
    RegistroAcceso:
      type: object
      required: [eventoId, usuario, fecha, recurso, motivo, resultado]
      properties:
        eventoId: { type: string, format: uuid }
        usuario: { type: string }
        rol: { type: string }
        fecha: { type: string, format: date-time }
        recurso: { type: string, description: Por ejemplo historial/{pacienteId} }
        motivo: { type: string }
        resultado: { type: string, enum: [permitido, denegado] }
        correlacionId: { type: string }

# Claims que el proveedor de identidad debe emitir en el JWT (OIDC)
ClaimsDelToken:
  type: object
  required: [sub, iss, aud, exp, rol]
  properties:
    sub: { type: string }
    iss: { type: string }
    aud: { type: string }
    exp: { type: integer }
    rol: { type: string, enum: [paciente, medico_rural, especialista, gestor_red, auditor] }
    centroId: { type: string, description: Centro del médico rural o del paciente }
    especialidad: { type: string, description: Solo para especialistas }
# La plataforma valida firma, emisor, audiencia y vencimiento con las llaves públicas del proveedor.

openapi: 3.0.3
info:
  title: RedSalud Andina - Contrato hacia la farmacia del centro
  version: 1.0.0
  description: Propuesta. El canal está por acordar con la red.
paths:
  /farmacia/v1/recetas:
    post:
      summary: La farmacia del centro recibe una receta firmada (RF-05)
      description: Lo expone la farmacia; lo llama Receta electrónica desde su outbox.
      parameters:
        - name: Idempotency-Key
          in: header
          required: true
          description: Igual al recetaId; un reenvío no crea una segunda receta
          schema: { type: string, format: uuid }
      requestBody:
        required: true
        content:
          application/json:
            schema: { $ref: '#/components/schemas/RecetaFirmada' }
      responses:
        '202': { description: Receta recibida }
        '409': { description: La receta ya estaba recibida; la plataforma la marca como enviada }
        '400': { description: Receta incompleta o firma inválida }
components:
  schemas:
    RecetaFirmada:
      type: object
      required: [recetaId, centroId, pacienteId, especialistaId, emitidaEn, medicamentos, firma]
      properties:
        recetaId: { type: string, format: uuid }
        centroId: { type: string }
        pacienteId: { type: string }
        especialistaId: { type: string }
        registroProfesional: { type: string }
        emitidaEn: { type: string, format: date-time }
        medicamentos:
          type: array
          items:
            type: object
            required: [nombre, dosis]
            properties:
              nombre: { type: string }
              dosis: { type: string }
              indicaciones: { type: string }
        firma:
          type: object
          required: [algoritmo, valor]
          properties:
            algoritmo: { type: string }
            valor: { type: string }
            certificado: { type: string }

# Valor guardado en Redis con la clave historial:{pacienteId}
HistorialEnVista:
  type: object
  required: [pacienteId, actualizadoEn]
  properties:
    pacienteId: { type: string }
    actualizadoEn: { type: string, format: date-time }
    antecedentes: { type: array, items: { type: string } }
    diagnosticos: { type: array, items: { type: string } }
# El sincronizador traduce cada respuesta SOAP del legado a este esquema.
# Pendiente: el WSDL y las operaciones del legado, y su modelo de tablas para la consulta puntual.

# Cuerpo del mensaje SQS de auditoría; se guarda sin cambios en S3 Object Lock
RegistroAcceso:
  type: object
  required: [eventoId, usuario, fecha, recurso, motivo, resultado]
  properties:
    eventoId: { type: string, format: uuid }
    usuario: { type: string }
    rol: { type: string }
    fecha: { type: string, format: date-time }
    recurso: { type: string, description: Por ejemplo historial/{pacienteId} }
    motivo: { type: string }
    resultado: { type: string, enum: [permitido, denegado] }
    correlacionId: { type: string }
